    if (pid == 0) {
        close(listen_fd);
        handle_client(client_fd, &client_addr);
        close(client_fd);
        _exit(0);
    } else if (pid > 0) {
        close(client_fd);
    } else {
        perror("fork");
        close(client_fd);
    }
